package com.myaaptha.domain.relationship;
import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import com.myaaptha.domain.contacts.AddressBookService;import com.myaaptha.domain.contacts.AddressBookController.ContactInput;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest @AutoConfigureMockMvc class ReviewedTreesTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired AddressBookService book;@Autowired JdbcTemplate db;
 record Account(long id,String token){}
 Account account()throws Exception{String name="trees-"+UUID.randomUUID();var created=mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("username",name,"password","TreeReviewSecret123","phoneNumber","+1775"+String.format("%010d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%10000000000L)))))).andExpect(status().isOk()).andReturn();long id=json.readTree(created.getResponse().getContentAsString()).get("id").asLong();var login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("identifier",name,"password","TreeReviewSecret123")))).andExpect(status().isOk()).andReturn();return new Account(id,"Bearer "+json.readTree(login.getResponse().getContentAsString()).get("accessToken").asText());}
 void contacts(Account a,int count,String organization,String group){List<ContactInput> batch=new ArrayList<>();for(int i=0;i<count;i++){batch.add(new ContactInput("Person "+i+" Example",List.of("+1888"+String.format("%010d",i)),List.of(),organization,group==null?List.of():List.of(group)));if(batch.size()==100){book.save(a.id,batch,"csv");batch.clear();}}if(!batch.isEmpty())book.save(a.id,batch,"csv");}
 JsonNode read(Account a,String path)throws Exception{return json.readTree(mvc.perform(get(path).header("Authorization",a.token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 JsonNode save(Account a,JsonNode tree)throws Exception{ObjectNode body=json.createObjectNode().put("name",tree.get("name").asText()).put("sourceKey",tree.get("sourceKey").asText()).put("reason",tree.get("reason").asText()).put("reviewed",true);body.set("nodes",tree.get("nodes"));return json.readTree(mvc.perform(post("/api/relationship-trees").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());}
 @Test void suggestsAcrossTwoThousandContactsWithoutSingletonsAndKeepsOwnersPrivate()throws Exception{
  Account a=account(),other=account();contacts(a,2000,"Acme Office","College classmates");long users=db.queryForObject("SELECT COUNT(*) FROM users",Long.class);JsonNode response=read(a,"/api/relationship-trees/suggestions");assertThat(response.get("scannedContacts").asInt()).isEqualTo(2000);assertThat(response.get("totalSuggestions").asInt()).isGreaterThanOrEqualTo(2);for(JsonNode card:response.get("items")){assertThat(card.get("count").asInt()).isGreaterThanOrEqualTo(3);assertThat(card.get("preview").size()).isLessThanOrEqualTo(6);}String key=response.get("items").get(0).get("key").asText();var draft=read(a,"/api/relationship-trees/suggestions/"+key);assertThat(draft.get("nodes").size()).isEqualTo(2000);assertThat(read(other,"/api/relationship-trees/suggestions").get("totalSuggestions").asInt()).isZero();mvc.perform(get("/api/relationship-trees/suggestions/"+key).header("Authorization",other.token)).andExpect(status().isNotFound());assertThat(db.queryForObject("SELECT COUNT(*) FROM users",Long.class)).isEqualTo(users);assertThat(db.queryForObject("SELECT COUNT(*) FROM relationships WHERE owner_user_id=?",Long.class,a.id)).isZero();
 }
 @Test void reviewedSaveSupportsEditingAndIdempotencyWithoutInvites()throws Exception{
  Account a=account(),other=account();contacts(a,4,"Office","Friends from college");var list=read(a,"/api/relationship-trees/suggestions");var draft=read(a,"/api/relationship-trees/suggestions/"+list.get("items").get(0).get("key").asText());var nodes=(ArrayNode)draft.get("nodes");nodes.remove(3);((ObjectNode)nodes.get(0)).put("relation","Friend");((ObjectNode)nodes.get(0)).put("gender","FEMALE");var saved=save(a,draft);assertThat(saved.get("nodes").get(0).get("gender").asText()).isEqualTo("FEMALE");long id=saved.get("id").asLong();assertThat(save(a,draft).get("id").asLong()).isEqualTo(id);assertThat(saved.get("nodes").size()).isEqualTo(3);mvc.perform(get("/api/relationship-trees/"+id).header("Authorization",other.token)).andExpect(status().isNotFound());ObjectNode edit=json.createObjectNode().put("name","Reviewed college tree").put("reviewed",true).put("version",saved.get("version").asLong());edit.set("nodes",saved.get("nodes"));mvc.perform(post("/api/relationship-trees/"+id+"/update").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(edit))).andExpect(status().isOk()).andExpect(jsonPath("$.name").value("Reviewed college tree"));mvc.perform(post("/api/relationship-trees/"+id+"/update").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(edit))).andExpect(status().isConflict());assertThat(db.queryForObject("SELECT COUNT(*) FROM circle_members WHERE user_id=?",Long.class,a.id)).isZero();mvc.perform(post("/api/relationship-trees/"+id+"/delete").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());assertThat(read(a,"/api/address-book").get("total").asInt()).isEqualTo(4);
 }
 @Test void refusesUnreviewedSmallCyclicAndForeignContactTrees()throws Exception{
  Account a=account(),other=account();contacts(a,2,"Two people",null);assertThat(read(a,"/api/relationship-trees/suggestions").get("totalSuggestions").asInt()).isZero();List<Map<String,Object>> nodes=new ArrayList<>();for(int i=0;i<3;i++)nodes.add(new HashMap<>(Map.of("key","n"+i,"name","Person "+i,"relation","Connection")));ObjectNode input=json.valueToTree(Map.of("name","Manual tree","nodes",nodes,"reviewed",false));mvc.perform(post("/api/relationship-trees").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isBadRequest());input.put("reviewed",true);((ObjectNode)input.get("nodes").get(0)).put("parentKey","n1");((ObjectNode)input.get("nodes").get(1)).put("parentKey","n0");mvc.perform(post("/api/relationship-trees").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isBadRequest());input.set("nodes",json.valueToTree(nodes));long foreign=book.allEntries(a.id).getFirst().id();((ObjectNode)input.get("nodes").get(0)).put("contactId",foreign);mvc.perform(post("/api/relationship-trees").header("Authorization",other.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(input))).andExpect(status().isNotFound());
 }
 @Test void dismissRestoreAndMultipleManualTreesWork()throws Exception{
  Account a=account();contacts(a,3,"Lab","School friends");var suggestions=read(a,"/api/relationship-trees/suggestions");String key=suggestions.get("items").get(0).get("key").asText();mvc.perform(post("/api/relationship-trees/suggestions/dismiss").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("key",key)))).andExpect(status().isOk());assertThat(read(a,"/api/relationship-trees/suggestions").get("dismissedCount").asInt()).isEqualTo(1);mvc.perform(post("/api/relationship-trees/suggestions/restore").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());assertThat(read(a,"/api/relationship-trees/suggestions").get("dismissedCount").asInt()).isZero();for(int i=0;i<4;i++){var nodes=List.of(Map.of("key","a","name","Alex","relation","Friend"),Map.of("key","b","name","Sam","relation","Colleague"),Map.of("key","c","name","Maya","relation","Sister"));mvc.perform(post("/api/relationship-trees").header("Authorization",a.token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("name","Custom tree "+i,"nodes",nodes,"reviewed",true)))).andExpect(status().isOk());}assertThat(read(a,"/api/relationship-trees").get("items").size()).isEqualTo(4);
 }
}
